from qiskit import QuantumCircuit
from qiskit.circuit.library import MCXGate

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int],
                 ancilla_qubits: list[int]) -> None:
    a = [10, 2, 8, 9]
    target = 2

    # Use 4 ancillas for sum bits, 1 for carry/flag
    sum_ancillas = ancilla_qubits[:4]
    carry_flag = ancilla_qubits[4]

    # Compute sum using ripple-carry adder
    # For each of the 4 numbers, add its value to the running sum
    for val in a:
        if val == 0:
            continue
        bits = [(val >> j) & 1 for j in range(4)]

        # Add constant val to sum using controlled additions
        # For each bit position j, if bits[j] is 1, we need to add 1 at that position
        for j in range(4):
            if bits[j]:
                qc.cx(problem_qubits[0], sum_ancillas[j])

        # Handle carry propagation for this addition
        for j in range(3):
            # If both sum_ancillas[j] and the new bit are 1, we have a carry
            # Use Toffoli gate to detect carry: problem_qubits[0] AND sum_ancillas[j]
            # Then flip sum_ancillas[j+1] and uncompute
            qc.ccx(problem_qubits[0], sum_ancillas[j], sum_ancillas[j+1])

    # Target = 2 = binary 0010 (LSB first: bit0=0, bit1=1, bit2=0, bit3=0)
    target_bits = [0, 1, 0, 0]

    # Mark states where sum == target
    for j in range(4):
        if target_bits[j] == 0:
            qc.x(sum_ancillas[j])

    mcx = MCXGate(4)
    qc.append(mcx, sum_ancillas + [carry_flag])
    qc.z(carry_flag)
    qc.append(mcx, sum_ancillas + [carry_flag])

    for j in range(4):
        if target_bits[j] == 0:
            qc.x(sum_ancillas[j])

    # Uncompute
    for val in reversed(a):
        if val == 0:
            continue
        bits = [(val >> j) & 1 for j in range(4)]

        for j in reversed(range(3)):
            qc.ccx(problem_qubits[0], sum_ancillas[j], sum_ancillas[j+1])

        for j in reversed(range(4)):
            if bits[j]:
                qc.cx(problem_qubits[0], sum_ancillas[j])

