import math
from qiskit import QuantumCircuit
def build_oracle(qc: QuantumCircuit, problem_qubits: list[int],
                 ancilla_qubits: list[int]) -> None:
    # pattern: "001010" (length 6)
    pattern = [0, 0, 1, 0, 1, 0]

    a0, a1, a_comb = ancilla_qubits[0], ancilla_qubits[1], ancilla_qubits[2]

    # --- Offset 0 check: compare pattern with bits at positions 0..5 ---
    controls0 = []
    for i in range(6):
        if pattern[i] == 0:
            qc.x(problem_qubits[i])
            controls0.append(problem_qubits[i])
        else:
            controls0.append(problem_qubits[i])
    qc.mcx(controls0, a0)
    for i in range(6):
        if pattern[i] == 0:
            qc.x(problem_qubits[i])

    # --- Offset 1 check: compare pattern with bits at positions 1..6 ---
    controls1 = []
    for i in range(6):
        if pattern[i] == 0:
            qc.x(problem_qubits[i+1])
            controls1.append(problem_qubits[i+1])
        else:
            controls1.append(problem_qubits[i+1])
    qc.mcx(controls1, a1)
    for i in range(6):
        if pattern[i] == 0:
            qc.x(problem_qubits[i+1])

    # --- Combine: phase if a0 or a1 is 1 ---
    # Compute OR: a_comb = a0 OR a1 using Toffoli-based approach
    # OR(a,b) = a ⊕ b ⊕ (a ∧ b)
    qc.ccx(a0, a1, a_comb)
    qc.cx(a0, a_comb)
    qc.cx(a1, a_comb)

    # Apply phase
    qc.z(a_comb)

    # Uncompute OR
    qc.cx(a1, a_comb)
    qc.cx(a0, a_comb)
    qc.ccx(a0, a1, a_comb)

    # Uncompute offset 1
    for i in range(5, -1, -1):
        if pattern[i] == 0:
            qc.x(problem_qubits[i+1])
    qc.mcx(controls1, a1)
    for i in range(5, -1, -1):
        if pattern[i] == 0:
            qc.x(problem_qubits[i+1])

    # Uncompute offset 0
    for i in range(5, -1, -1):
        if pattern[i] == 0:
            qc.x(problem_qubits[i])
    qc.mcx(controls0, a0)
    for i in range(5, -1, -1):
        if pattern[i] == 0:
